pub(crate) fn push_order_document_where(
    qb: &mut sqlx::QueryBuilder<'_, sqlx::Postgres>,
    w: &crate::orders::OrderDocumentWhereInput,
) -> bool {
    let mut any = false;
    if let Some(f) = &w.id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "id", f);
    }
    if let Some(f) = &w.id_uuid {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_nullable_filter(qb, "id_uuid", f);
    }
    if let Some(f) = &w.order_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_filter(qb, "order_id", f);
    }
    if let Some(f) = &w.file_name {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "file_name", f);
    }
    if let Some(f) = &w.mime_type {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "mime_type", f);
    }
    if let Some(f) = &w.file_size {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_filter(qb, "file_size", f);
    }
    if let Some(f) = &w.page_count {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_nullable_filter(qb, "page_count", f);
    }
    if let Some(f) = &w.uploaded_at {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_datetime_filter(qb, "uploaded_at", f);
    }
    if let Some(f) = &w.deleted_at {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_datetime_nullable_filter(qb, "deleted_at", f);
    }
    if let Some(f) = &w.delete_document {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_bool_nullable_filter(qb, "delete_document", f);
    }
    if let Some(rel) = &w.orders {
        if let Some(sub) = &rel.is {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("EXISTS (SELECT 1 FROM \"orders\" t WHERE t.\"id\" = \"orders_documents\".\"order_id\" AND (");
            if !crate::engine::sqlx_postgres::orders::push_order_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.is_not {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT EXISTS (SELECT 1 FROM \"orders\" t WHERE t.\"id\" = \"orders_documents\".\"order_id\" AND (");
            if !crate::engine::sqlx_postgres::orders::push_order_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
    }
    if let Some(group) = &w.and {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("(");
            if !push_order_document_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    if let Some(group) = &w.or {
        if any {
            qb.push(" AND ");
        }
        any = true;
        qb.push("(");
        let mut first = true;
        for sub in group {
            if !first {
                qb.push(" OR ");
            }
            first = false;
            qb.push("(");
            if !push_order_document_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
        qb.push(")");
    }
    if let Some(group) = &w.not {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT (");
            if !push_order_document_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    any
}

impl crate::orders::OrderDocument {
    pub async fn find_unique<'e, E>(
        executor: E,
        w: &crate::orders::OrderDocumentWhereUniqueInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let cols = "\"id\", \"id_uuid\", \"order_id\", \"file_name\", \"mime_type\", \"file_size\", \"page_count\", \"uploaded_at\", \"deleted_at\", \"delete_document\"";
        let mut qb =
            sqlx::QueryBuilder::new(format!(r#"SELECT {} FROM "orders_documents" WHERE "#, cols,));
        // For v1, support only the @id field. Composite uniques are out of scope.
        // The WhereUniqueInput has Option<T> per @id/@unique field; we pick the
        // first Some(). Multi-Some inputs cover composite uniques — TODO Task v2.
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(value.clone());
        } else {
            return Ok(None);
        }
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

