impl crate::orders::ProviderOrder {
    pub async fn create_many<'e, E>(
        executor: E,
        inputs: &[crate::orders::ProviderOrderUncheckedCreateInput],
    ) -> sqlx::Result<u64>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        if inputs.is_empty() {
            return Ok(0);
        }
        let mut qb = sqlx::QueryBuilder::new(
            r#"INSERT INTO "provider_orders" ("order_id", "provider_location_id", "provider_name", "provider_address", "provider_city", "provider_state", "provider_zip", "provider_phone", "provider_fax", "service_start", "service_end", "order_flags", "record_types", "provider_notes") "#,
        );
        qb.push_values(inputs, |mut row, input| {
            row.push_bind(input.order_id);
            row.push_bind(input.provider_location_id);
            row.push_bind(input.provider_name.clone());
            row.push_bind(input.provider_address.clone());
            row.push_bind(input.provider_city.clone());
            row.push_bind(input.provider_state.clone());
            row.push_bind(input.provider_zip.clone());
            row.push_bind(input.provider_phone.clone());
            row.push_bind(input.provider_fax.clone());
            row.push_bind(input.service_start);
            row.push_bind(input.service_end);
            row.push_bind(input.order_flags.clone());
            row.push_bind(input.record_types.clone());
            row.push_bind(input.provider_notes.clone());
        });
        let result = qb.build().execute(executor).await?;
        Ok(result.rows_affected())
    }
}

